import {validateAccount,score,contributions,evaluate,queue,csv} from './ml.mjs';
const $=id=>document.getElementById(id),pct=v=>(100*v).toFixed(1)+'%',money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const names={logistic:'Logistic regression',forest:'Random forest'},labels={days_past_due:'Days past due',credit_score:'Credit score',monthly_income:'Monthly income',balance:'Balance',utilization:'Utilization',missed_payments_6m:'Missed payments',portfolio:'Portfolio'};
let data,key='logistic',threshold=.26,account,page=0,active='score',filtered=[],scored=[];
const titles={score:['Account studio','Explore how account characteristics change a model’s risk estimate.'],lab:['Model lab','Compare discrimination and explore the precision–recall tradeoff.'],queue:['Review queue','Explore and export scores for 500 unlabeled synthetic accounts.'],method:['Method & sources','A transparent, reproducible experiment with a temporal evaluation design.']};
function tab(id){if(!titles[id])return;active=id;document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('page-title').textContent=titles[id][0];$('page-subtitle').textContent=titles[id][1];history.replaceState(null,'','#'+id);}
function formAccount(){const f=new FormData($('account-form'));return validateAccount({days_past_due:Number(f.get('days_past_due')),credit_score:Number(f.get('credit_score')),monthly_income:f.get('monthly_income').trim()===''?null:Number(f.get('monthly_income')),balance:Number(f.get('balance')),utilization:Number(f.get('utilization'))/100,missed_payments_6m:Number(f.get('missed_payments_6m')),portfolio:f.get('portfolio')});}
function fillForm(a){for(const [k,v] of Object.entries(a)){const el=$('account-form').elements.namedItem(k);if(el)el.value=v===null?'':k==='utilization'?v*100:v;}account=validateAccount(a);renderScore();}
function scoreForm(){try{account=formAccount();$('form-error').hidden=true;renderScore();}catch(e){$('form-error').textContent=e.message;$('form-error').hidden=false;}}
function renderScore(){const m=data.models[key],p=score(m,account);$('probability').textContent=(p*100).toFixed(1);$('risk-fill').style.width=pct(p);$('cutoff-marker').style.left=pct(threshold);$('cutoff-label').textContent='Review cutoff · '+Math.round(threshold*100)+'%';$('decision').textContent=p>=threshold?'Flagged for review':'Below review threshold';$('decision-dot').style.background=p>=threshold?'#ffc982':'#98eac8';$('model-caption').textContent=names[key];let row=data.testMetrics.find(r=>r.model===(key==='logistic'?'Logistic Regression':'Random Forest'));$('auc').textContent=row.roc_auc.toFixed(3);
 const warnings=[];for(const [k,bounds] of Object.entries(data.trainingRanges||{})){if(account[k]!==null&&(account[k]<bounds[0]||account[k]>bounds[1]))warnings.push(labels[k]);}
 $('range-note').textContent=warnings.length?'Outside observed training range: '+warnings.join(', ')+'. Treat this scenario cautiously.':account.monthly_income===null?'Income is imputed with the training median: '+money(m.medians[2])+'.':'Account inputs fall within observed numeric training ranges.';
 let rows,max;
 if(key==='logistic'){rows=contributions(m,account);max=Math.max(...rows.map(r=>Math.abs(r.value)),.01);$('explain-title').textContent='What moves this estimate?';$('explain-tag').textContent='LOCAL · LOG-ODDS';$('explain-note').textContent=`Signed contributions relative to training means, plus portfolio encoding. Positive raises log-odds; negative lowers it. Intercept: ${m.intercept.toFixed(3)}. These are not percentage-point effects or causal explanations.`;}
 else{rows=[...data.importance].sort((a,b)=>b.mean_auc_drop-a.mean_auc_drop).map(r=>({feature:r.feature,value:r.mean_auc_drop}));max=Math.max(...rows.map(r=>Math.abs(r.value)),.01);$('explain-title').textContent='Global drivers · selected logistic model';$('explain-tag').textContent='GLOBAL · TEST AUC DROP';$('explain-note').textContent='This chart describes the selected logistic model, not an individual random forest score. Values are mean test ROC-AUC drops across eight permutations. Random forest local attribution is not included.';}
 $('explanation-bars').replaceChildren(...rows.map(r=>{const el=document.createElement('div');el.className='bar-row';const label=document.createElement('span');label.textContent=labels[r.feature];const track=document.createElement('div');track.className='bar-track';const bar=document.createElement('div');bar.className='bar-fill';bar.style.width=(Math.abs(r.value)/max*100)+'%';bar.style.background=r.value>=0?'#278d7d':'#9f89bd';track.append(bar);const val=document.createElement('span');val.className='bar-num';val.textContent=(r.value>=0?'+':'')+r.value.toFixed(3);el.append(label,track,val);return el;}));}
function renderLab(){const e=evaluate(data.holdout,key,threshold);$('precision').textContent=pct(e.precision);$('recall').textContent=pct(e.recall);$('flagged').textContent=e.flagged;$('matrix').replaceChildren(...[['True negatives',e.tn],['False positives',e.fp],['False negatives',e.fn],['True positives',e.tp]].map(([name,value])=>{let d=document.createElement('div'),n=document.createElement('strong'),l=document.createElement('span');n.textContent=value;l.textContent=name;d.append(n,l);return d;}));}
function renderQueue(){scored=queue(data.accounts,data.models,key,threshold);const flag=scored.filter(a=>a.probability>=threshold);$('queue-flagged').textContent=flag.length;$('queue-balance').textContent=money(flag.reduce((s,a)=>s+a.balance,0));const f=$('queue-filter').value,q=$('search').value.trim();filtered=scored.filter(a=>(f==='all'||(f==='flagged'?a.probability>=threshold:a.probability<threshold))&&(!q||String(a.account_id).includes(q)));const pages=Math.ceil(filtered.length/20);page=Math.max(0,Math.min(page,pages-1));$('queue-count').textContent=filtered.length+' accounts';$('page-count').textContent=pages?`Page ${page+1} of ${pages}`:'No matches';$('prev').disabled=page===0;$('next').disabled=page+1>=pages;
 $('queue-rows').replaceChildren(...filtered.slice(page*20,page*20+20).map(a=>{const tr=document.createElement('tr');for(const v of [a.account_id,a.portfolio,money(a.balance),a.days_past_due,pct(a.probability)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}tr.children[4].className='prob-cell';const status=document.createElement('td'),pill=document.createElement('span');pill.className='risk-pill'+(a.probability>=threshold?'':' clear');pill.textContent=a.probability>=threshold?'Review':'Below cutoff';status.append(pill);const action=document.createElement('td'),b=document.createElement('button');b.className='quiet';b.textContent='Inspect ↗';b.setAttribute('aria-label','Inspect account '+a.account_id);b.onclick=()=>{fillForm(a);tab('score');window.scrollTo({top:0,behavior:'smooth'});};action.append(b);tr.append(status,action);return tr;}));if(!filtered.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=7;td.textContent='No accounts match these filters.';tr.append(td);$('queue-rows').append(tr);}}
function update(){key=$('model').value;threshold=Number($('threshold').value)/100;$('threshold-value').textContent=Math.round(threshold*100)+'%';renderScore();renderLab();renderQueue();}
function renderComparison(){$('comparison').replaceChildren(...data.testMetrics.map(r=>{const tr=document.createElement('tr'),v=data.validationMetrics.find(x=>x.model===r.model);for(const value of [r.model+(r.model==='Logistic Regression'?' · selected':''),r.roc_auc.toFixed(3),r.average_precision.toFixed(3),r.brier.toFixed(3),v.roc_auc.toFixed(3)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}if(r.model==='Logistic Regression')tr.children[0].className='model-selected';return tr;}));
 const coords=pts=>pts.map(([x,y])=>`${50+x*350},${270-y*240}`).join(' ');$('roc-chart').innerHTML=`<svg viewBox="0 0 440 310" role="img" aria-label="Test ROC curves: logistic regression AUC 0.721, random forest AUC 0.712, baseline 0.5"><g stroke="#e6ede5" stroke-width="1">${[0,.25,.5,.75,1].map(t=>`<path d="M50 ${270-t*240}H400"/>`).join('')}</g><path d="M50 30V270H400" fill="none" stroke="#9faf9e"/><path d="M50 270L400 30" stroke="#a3aea1" stroke-dasharray="5 5"/><polyline points="${coords(data.roc.logistic)}" fill="none" stroke="#167d70" stroke-width="2.5"/><polyline points="${coords(data.roc.forest)}" fill="none" stroke="#8163ab" stroke-width="2.5"/><g fill="#6a7b6d" font-size="10" font-family="system-ui"><text x="50" y="286">0</text><text x="217" y="286">0.5</text><text x="395" y="286">1</text><text x="30" y="273">0</text><text x="21" y="152">0.5</text><text x="30" y="34">1</text><text x="185" y="305">False positive rate</text><text transform="translate(12 205) rotate(-90)">True positive rate</text></g></svg>`;}
function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});const properties={days_past_due:{type:'integer',minimum:0,maximum:89},credit_score:{type:'integer',minimum:420,maximum:820},monthly_income:{type:['number','null'],minimum:1,maximum:1000000},balance:{type:'number',minimum:0,maximum:1000000},utilization:{type:'number',minimum:0,maximum:1},missed_payments_6m:{type:'integer',minimum:0,maximum:50},portfolio:{type:'string',enum:['Auto','Credit Card','Medical','Personal Loan']}};
 Promise.resolve(c.registerTool({name:'score_synthetic_account',title:'Score a synthetic account',description:'Set account inputs in the visible studio and calculate estimated synthetic 90-day delinquency probability with the selected model and threshold.',inputSchema:{type:'object',properties,required:Object.keys(properties),additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const a=validateAccount(input);fillForm(a);tab('score');const p=score(data.models[key],a);return {model:key,probability:p,threshold,reviewFlag:p>=threshold};}},{signal:controller.signal})).catch(()=>{});
}
window.addEventListener('hashchange',()=>{if(data)tab(location.hash.slice(1)||'score');});
$('account-form').onsubmit=e=>{e.preventDefault();scoreForm();};$('reset').onclick=()=>{$('account-form').reset();scoreForm();};$('model').onchange=update;$('threshold').oninput=update;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('queue-filter').onchange=()=>{page=0;renderQueue();};$('search').oninput=()=>{page=0;renderQueue();};$('prev').onclick=()=>{page--;renderQueue();};$('next').onclick=()=>{page++;renderQueue();};$('download').onclick=()=>{const blob=new Blob([csv(filtered,threshold,key)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`synthetic-risk-scores-${key}-${Math.round(threshold*100)}pct.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const r=await fetch('./data.json');if(!r.ok)throw new Error('Could not load model data.');data=await r.json();account=formAccount();renderComparison();update();$('loading').hidden=true;tab(location.hash.slice(1)||'score');registerTools();}catch(e){$('loading').hidden=true;$('fatal').hidden=false;$('fatal').textContent='Unable to load the app. Refresh to try again. '+e.message;}
